	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		WeatherObservation
	 */
		public WeatherObservation createWeatherObservation( CreateWeatherObservationCommand command ) {

		WeatherObservation entity = new WeatherObservation();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWeatherObservationId( command.getWeatherObservationId() );
            entity.setObservationTime( command.getObservationTime() );
            entity.setTemperatureC( command.getTemperatureC() );
            entity.setPrecipitationMm( command.getPrecipitationMm() );
            entity.setWindSpeedMps( command.getWindSpeedMps() );
            entity.setHumidity( command.getHumidity() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of WeatherObservation {0} ", entity.toString() );

		return entity;
	}

