            entity.setWeatherObservationId( command.getWeatherObservationId() );
            entity.setObservationTime( command.getObservationTime() );
            entity.setTemperatureC( command.getTemperatureC() );
            entity.setPrecipitationMm( command.getPrecipitationMm() );
            entity.setWindSpeedMps( command.getWindSpeedMps() );
            entity.setHumidity( command.getHumidity() );
            entity.setStation( command.getStation() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

